<?php
$pdo=db();$canReview=in_array($user['role'],['Administrator','Head'],true);$canReport=in_array($user['role'],['Administrator','Head','Teacher'],true);$q=trim((string)($_GET['q']??''));$statusFilter=(string)($_GET['status']??'');$categoryFilter=(string)($_GET['category']??'');$incidents=[];$learners=[];$reviewers=[];
try {
    $where=[];$params=[];if(!$canReview){$where[]='i.reported_by=:reporter';$params['reporter']=(int)$user['id'];}if($q!==''){$where[]='(s.first_name LIKE :first OR s.last_name LIKE :last OR s.admission_no LIKE :admission)';$like='%'.$q.'%';$params+=['first'=>$like,'last'=>$like,'admission'=>$like];}if(in_array($statusFilter,['Reported','Under Review','Resolved'],true)){$where[]='i.status=:status';$params['status']=$statusFilter;}if(in_array($categoryFilter,['Discipline','Bullying','Attendance','Wellbeing','Safety','Property damage','Academic integrity','Other'],true)){$where[]='i.category=:category';$params['category']=$categoryFilter;}$sql='SELECT i.*,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream,r.full_name AS reporter,a.full_name AS assignee,v.full_name AS reviewer FROM student_incidents i JOIN students s ON s.id=i.student_id LEFT JOIN users r ON r.id=i.reported_by LEFT JOIN users a ON a.id=i.assigned_to LEFT JOIN users v ON v.id=i.reviewed_by';if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY FIELD(i.severity,\'Critical\',\'High\',\'Moderate\',\'Low\'),FIELD(i.status,\'Reported\',\'Under Review\',\'Resolved\'),i.incident_on DESC,i.id DESC LIMIT 200';$stmt=$pdo->prepare($sql);$stmt->execute($params);$incidents=$stmt->fetchAll();
    if($canReview){$learners=$pdo->query("SELECT id,admission_no,first_name,last_name,form_level,stream FROM students WHERE status='Active' ORDER BY form_level,stream,last_name,first_name LIMIT 2000")->fetchAll();$reviewers=$pdo->query("SELECT id,full_name,role FROM users WHERE active=1 AND role IN ('Administrator','Head','Teacher') ORDER BY full_name")->fetchAll();}
    elseif($user['role']==='Teacher'){$stmt=$pdo->prepare("SELECT DISTINCT s.id,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream FROM students s JOIN class_groups cg ON cg.academic_year=YEAR(CURDATE()) AND cg.form_level=s.form_level AND cg.stream=COALESCE(s.stream,'') LEFT JOIN class_subjects cs ON cs.class_id=cg.id WHERE s.status='Active' AND (cg.class_teacher_id=:class_teacher OR cs.teacher_id=:subject_teacher) ORDER BY s.form_level,s.stream,s.last_name,s.first_name LIMIT 2000");$stmt->execute(['class_teacher'=>$user['id'],'subject_teacher'=>$user['id']]);$learners=$stmt->fetchAll();}
} catch(Throwable $e){error_log('Welfare page failed: '.$e->getMessage());echo '<section class="panel settings-panel"><h1>Welfare records setup required</h1><p>An administrator should import <code>database/migrations/011_student_welfare.sql</code> into the school database, then reload this page.</p></section>';return;}
?>
<div class="page-heading"><div><div class="eyebrow">STUDENT SUPPORT · CONFIDENTIAL</div><h1>Welfare & discipline</h1><p class="subheading">Record concerns, document leadership follow-up and keep an accountable history.</p></div></div>
<section class="panel info-panel academic-note"><h2>Confidential student information</h2><p>Use factual, respectful notes and record only information needed for school follow-up. Do not enter medical diagnoses or attach sensitive documents. Teachers see only reports they submitted; full case details are restricted to Administrators and Heads.</p></section>
<?php if($canReport): ?><section class="panel settings-panel"><h2>Report an incident or concern</h2><p>Reports are confidential and are not sent to guardians automatically. Use the school’s safeguarding process for urgent safety concerns.</p><?php if(!$learners): ?><div class="alert alert-warn"><?= $user['role']==='Teacher'?'No currently assigned active learners are available. Check class and subject assignments in Academics.':'Add active learner records before submitting a report.' ?></div><?php else: ?><form method="post" action="actions/incident_report.php" class="inline-form fee-schedule-form"><?= csrf_field() ?><label>Learner<select name="student_id" required><option value="">Select learner</option><?php foreach($learners as $l): ?><option value="<?= (int)$l['id'] ?>"><?= h('Form '.$l['form_level'].($l['stream']?' '.$l['stream']:'').' · '.$l['first_name'].' '.$l['last_name'].' ('.$l['admission_no'].')') ?></option><?php endforeach; ?></select></label><label>Date of incident<input type="date" name="incident_on" max="<?= h(date('Y-m-d')) ?>" value="<?= h(date('Y-m-d')) ?>" required></label><label>Category<select name="category" required><?php foreach(['Discipline','Bullying','Attendance','Wellbeing','Safety','Property damage','Academic integrity','Other'] as $c): ?><option><?= h($c) ?></option><?php endforeach; ?></select></label><label>Severity<select name="severity" required><?php foreach(['Low','Moderate','High','Critical'] as $s): ?><option <?= $s==='Low'?'selected':'' ?>><?= h($s) ?></option><?php endforeach; ?></select></label><label class="full-width">Factual description<textarea name="description" rows="4" maxlength="5000" minlength="8" required placeholder="What was observed or reported? Include relevant context, without assumptions."></textarea></label><label class="full-width">Immediate support or action <span class="optional">Optional</span><textarea name="immediate_action" rows="3" maxlength="2000" placeholder="Any immediate support provided or safeguarding referral made"></textarea></label><button class="primary-button">Submit confidential report</button></form><?php endif; ?></section><?php endif; ?>
<section class="panel learners-panel"><form class="list-toolbar" method="get"><input type="hidden" name="page" value="welfare"><div class="search-box"><span>⌕</span><input name="q" value="<?= h($q) ?>" placeholder="Search learner name or admission number"></div><div class="toolbar-right"><select name="status" class="select-control"><option value="">All statuses</option><?php foreach(['Reported','Under Review','Resolved'] as $s): ?><option value="<?= h($s) ?>" <?= $statusFilter===$s?'selected':'' ?>><?= h($s) ?></option><?php endforeach; ?></select><select name="category" class="select-control"><option value="">All categories</option><?php foreach(['Discipline','Bullying','Attendance','Wellbeing','Safety','Property damage','Academic integrity','Other'] as $c): ?><option value="<?= h($c) ?>" <?= $categoryFilter===$c?'selected':'' ?>><?= h($c) ?></option><?php endforeach; ?></select><button class="outline-button">Filter</button></div></form></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2><?= $canReview?'Confidential incident register':'Reports submitted by you' ?></h2><p><?= count($incidents) ?> reports shown · maximum 200 per filter</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner / date</th><th>Category / severity</th><th>Report</th><th>Status / follow-up</th><?php if($canReview): ?><th>Leadership review</th><?php endif; ?></tr></thead><tbody><?php foreach($incidents as $i): ?><tr><td><b><?= h($i['first_name'].' '.$i['last_name']) ?></b><br><span class="muted-cell"><?= h($i['admission_no']) ?> · Form <?= (int)$i['form_level'] ?><?= $i['stream']?' '.h($i['stream']):'' ?></span><br><?= h(date('d M Y',strtotime($i['incident_on']))) ?></td><td><?= h($i['category']) ?><br><span class="consent-pill <?= in_array($i['severity'],['High','Critical'],true)?'pending':'granted' ?>"><?= h($i['severity']) ?></span></td><td><b>Reported by <?= h($i['reporter']??'Former staff') ?></b><p><?= nl2br(h($i['description'])) ?></p><?php if($i['immediate_action']): ?><details><summary>Immediate action</summary><p><?= nl2br(h($i['immediate_action'])) ?></p></details><?php endif; ?></td><td><span class="status-pill"><?= h($i['status']) ?></span><?php if($i['assignee']): ?><br><span class="muted-cell">Assigned to <?= h($i['assignee']) ?></span><?php endif; ?><?php if($i['resolution']): ?><details><summary>Outcome</summary><p><?= nl2br(h($i['resolution'])) ?></p></details><?php endif; ?><?php if($canReview&&$i['guardian_contacted_on']): ?><details><summary>Guardian contact recorded</summary><p><?= h($i['guardian_contact_method']) ?> · <?= h(date('d M Y',strtotime($i['guardian_contacted_on']))) ?><br><?= nl2br(h($i['guardian_contact_notes']??'')) ?></p></details><?php endif; ?></td><?php if($canReview): ?><td><details><summary>Update follow-up</summary><form method="post" action="actions/incident_followup.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="incident_id" value="<?= (int)$i['id'] ?>"><label>Status<select name="status"><?php foreach(['Reported','Under Review','Resolved'] as $s): ?><option <?= $i['status']===$s?'selected':'' ?>><?= h($s) ?></option><?php endforeach; ?></select></label><label>Assign follow-up to<select name="assigned_to"><option value="">Unassigned</option><?php foreach($reviewers as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (int)$i['assigned_to']===(int)$r['id']?'selected':'' ?>><?= h($r['full_name'].' · '.$r['role']) ?></option><?php endforeach; ?></select></label><label>Outcome / next steps<textarea name="resolution" rows="3" maxlength="4000" placeholder="Required when resolving"><?= h($i['resolution']??'') ?></textarea></label><label>Guardian contacted on <span class="optional">Optional</span><input type="date" name="guardian_contacted_on" max="<?= h(date('Y-m-d')) ?>" value="<?= h($i['guardian_contacted_on']??'') ?>"></label><label>Contact method<select name="guardian_contact_method"><option value="">Not recorded</option><?php foreach(['Phone','Meeting','Written','Other'] as $m): ?><option value="<?= h($m) ?>" <?= $i['guardian_contact_method']===$m?'selected':'' ?>><?= h($m) ?></option><?php endforeach; ?></select></label><label>Contact notes <span class="optional">Optional</span><input name="guardian_contact_notes" maxlength="500" value="<?= h($i['guardian_contact_notes']??'') ?>"></label><button class="primary-button">Save follow-up</button></form></details><?php endif; ?></td></tr><?php endforeach; if(!$incidents): ?><tr><td colspan="<?= $canReview?5:4 ?>" class="empty-cell">No confidential reports match this view.</td></tr><?php endif; ?></tbody></table></div></section>
